<style>
:root{--navy:#0c2c4d;--blue:#164b7a;--blue2:#2d6c9d;--gold:#c9a45c;--gold-pale:#f7efdE;--ink:#19334d;--muted:#6e7f90;--ivory:#fffdf8;--line:#e8e5dc;--mint:#eaf5ef;--sky:#edf5fb;--rose:#fff0ee;--lilac:#f3f0fb;--shadow:0 16px 42px rgba(12,44,77,.09);--shadow-hover:0 24px 54px rgba(12,44,77,.15)}
*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:95px}body{margin:0;overflow-x:hidden;background:linear-gradient(180deg,#fffdf8 0%,#f8fafb 52%,#fffdf8 100%);color:var(--ink);font-family:Inter,Arial,sans-serif;font-size:15px;line-height:1.65}img{max-width:100%}a{transition:color .2s ease}h1,h2,h3,h4,h5,h6{color:var(--navy);font-family:Georgia,'Times New Roman',serif}button,a{-webkit-tap-highlight-color:transparent}a:focus-visible,button:focus-visible{outline:3px solid var(--gold)!important;outline-offset:3px}
/* Full-bleed announcement strip */
.ajm-ticker{height:38px;min-height:38px;width:100%;display:flex;align-items:center;gap:14px;padding:4px clamp(12px,2.5vw,42px);position:relative;z-index:1040;color:#fff;background:linear-gradient(100deg,#092744,#124a78 62%,#1e608a);box-shadow:0 4px 15px #09274422}.ajm-ticker-label{display:flex;align-items:center;gap:8px;white-space:nowrap;flex:0 0 auto;color:#f2dca9;font-size:9px;font-weight:800;letter-spacing:1.2px}.ticker-live-dot{width:6px;height:6px;border-radius:50%;background:#e7c77f;box-shadow:0 0 0 4px #e7c77f20;animation:livePulse 2s infinite}.ajm-ticker-window{flex:1;min-width:0;overflow:hidden}.ajm-ticker-track{display:flex;align-items:center;width:max-content;animation:bulletin 48s linear infinite}.ajm-ticker-track span{display:flex;align-items:center;gap:9px;white-space:nowrap;padding:0 22px;border-right:1px solid #ffffff30;font-size:11px;font-weight:600}.ticker-toggle{width:27px;height:27px;flex:0 0 27px;display:grid;place-items:center;border:1px solid #ffffff65;border-radius:50%;background:#ffffff10;color:#fff;font-size:10px;transition:all .2s}.ticker-toggle:hover{background:var(--gold);color:var(--navy);transform:scale(1.06)}.ajm-ticker-track.is-paused{animation-play-state:paused}@keyframes bulletin{to{transform:translateX(-50%)}}@keyframes livePulse{50%{box-shadow:0 0 0 7px #e7c77f08;opacity:.7}}
/* Edge-to-edge glass navigation */
.navbar{width:100%;max-width:none;margin:0;padding:12px clamp(14px,3vw,48px);position:sticky;top:0;z-index:1030;border:0!important;border-bottom:1px solid #e6e8e7!important;border-radius:0;background:#fffdf8f2!important;backdrop-filter:blur(18px);box-shadow:0 8px 28px #0c2c4d0b!important}.navbar>.container-fluid{width:100%;max-width:1700px;margin:auto;padding:0;gap:18px}.navbar-brand{display:flex;align-items:center;gap:11px!important;margin:0;color:var(--navy)!important;font-size:clamp(1rem,1.45vw,1.4rem);font-weight:800;letter-spacing:-.5px;white-space:nowrap}.navbar-brand img{width:44px;height:44px;object-fit:contain;padding:3px;border-radius:13px!important;background:#fff;box-shadow:0 5px 15px #0c2c4d14}.navbar-collapse{flex-grow:0}.navbar-nav{align-items:center;gap:5px}.navbar .btn{margin:0!important;padding:10px 13px;border:1px solid transparent!important;border-radius:11px;font-size:12px;font-weight:800;white-space:nowrap;transition:transform .22s,box-shadow .22s,background .22s}.navbar .btn-outline-light{background:#f0f5fa;color:#244f75}.navbar .btn-outline-light:nth-child(2){background:#edf6f0;color:#36745d}.navbar .btn-outline-light:nth-child(3){background:#fbf2e4;color:#946d2e}.navbar .btn-outline-light:nth-child(4){background:#f4effb;color:#6a55a0}.navbar .btn-light{background:var(--navy)!important;color:#fff!important;box-shadow:0 7px 16px #0c2c4d1e}.navbar .btn:hover{transform:translateY(-2px);box-shadow:0 10px 22px #0c2c4d18}.navbar-toggler{border:1px solid #dfe5e9!important;border-radius:10px;padding:7px 9px;box-shadow:none!important}
/* Hero composition */
.ajm-hero{position:relative;max-width:1700px;margin:28px auto 0;padding:0 clamp(16px,3.2vw,54px)}.hero-panel{position:relative;min-height:370px;overflow:hidden;display:grid;grid-template-columns:minmax(300px,.84fr) minmax(0,1.16fr);align-items:stretch;border:1px solid #e8e7df;border-radius:27px;background:linear-gradient(110deg,#fffdf8 0%,#fffdf8 40%,#edf5f7 100%);box-shadow:var(--shadow)}.hero-copy{position:relative;z-index:2;display:flex;flex-direction:column;align-items:flex-start;justify-content:center;padding:clamp(24px,4vw,58px)}.eyebrow{display:flex;align-items:center;gap:9px;margin-bottom:14px;color:#6c7e8c;font-size:10px;font-weight:800;letter-spacing:1.7px;text-transform:uppercase}.eyebrow:before{content:'';width:24px;height:2px;background:var(--gold)}.hero-copy h1{max-width:580px;margin:0 0 14px;font-size:clamp(2.5rem,4.2vw,4.5rem);font-weight:700;line-height:.99;letter-spacing:-2px}.hero-copy h1 span{color:#2c668b}.hero-copy p{max-width:470px;margin:0;color:#65778a;font-size:14px;line-height:1.8}.hero-actions{display:flex;align-items:center;flex-wrap:wrap;gap:10px;margin:23px 0 0}.hero-link{display:inline-flex;align-items:center;justify-content:center;gap:10px;padding:12px 17px;border-radius:999px;text-decoration:none;font-size:12px;font-weight:800;transition:transform .22s,box-shadow .22s,background .22s}.hero-link:hover{transform:translateY(-2px)}.hero-link-primary{background:linear-gradient(120deg,#0b2c4c,#1d5b87);color:#fff;box-shadow:0 9px 20px #0c2c4d20}.hero-link-primary:hover{color:#fff;box-shadow:0 13px 26px #0c2c4d2b}.hero-link-secondary{border:1px solid #d6dfe4;background:#fff;color:var(--navy)}.hero-link-secondary:hover{background:#f4f8fa;color:var(--navy)}.hero-photo{position:relative;min-height:370px;overflow:hidden;background:#dbe8ed}.hero-photo:before{content:'';position:absolute;z-index:1;inset:0;background:linear-gradient(90deg,#fffdf8 0%,#fffdf82c 24%,transparent 60%),linear-gradient(0deg,#0b2c4c35,transparent 50%);pointer-events:none}.hero-photo #galleryCarousel{height:100%;min-height:370px;margin:0!important;border:0!important;border-radius:0!important;box-shadow:none!important;background:#e7eff1}.hero-photo #galleryCarousel .carousel-inner,.hero-photo #galleryCarousel .carousel-item{height:100%;min-height:370px}.hero-photo #galleryCarousel .carousel-inner img{height:100%!important;min-height:370px;max-height:510px;object-fit:cover;display:block;transition:transform 7s ease}.hero-photo #galleryCarousel .carousel-item.active img{animation:heroPhotoIn 1.1s ease both}.hero-photo .carousel-control-prev,.hero-photo .carousel-control-next{z-index:3;width:11%}.hero-photo .carousel-control-prev-icon,.hero-photo .carousel-control-next-icon{width:39px;height:39px;background-color:#0c2c4ddd;border-radius:50%;background-size:42%;box-shadow:0 5px 15px #09274428}.hero-photo .carousel-control-prev:hover .carousel-control-prev-icon,.hero-photo .carousel-control-next:hover .carousel-control-next-icon{background-color:var(--gold);transform:scale(1.08)}.hero-note{position:absolute;z-index:4;right:22px;bottom:22px;display:flex;align-items:center;gap:12px;padding:13px 17px;border:1px solid #ffffffaa;border-radius:16px;background:#fffdf2ed;box-shadow:0 12px 28px #0c2c4d1b;color:var(--navy);font-size:12px;font-weight:800;backdrop-filter:blur(10px)}.hero-note .icon-tile{width:39px;height:39px;border-radius:12px;background:#f8efd9;color:#98733a}.hero-note small{display:block;color:#78818b;font-size:10px;font-weight:600}.icon-tile{display:grid;place-items:center;flex:0 0 auto}.icon-tile svg,.quick-icon svg,.mini-icon svg{width:22px;height:22px;stroke:currentColor;fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}
/* Quick links appear immediately after hero */
.quick-access{position:relative;z-index:5;max-width:1580px;margin:-22px auto 0;padding:0 clamp(18px,3.5vw,58px)}.quick-panel{display:grid;grid-template-columns:170px repeat(4,minmax(0,1fr));gap:10px;align-items:stretch;padding:15px;border:1px solid #e8e9e4;border-radius:22px;background:#fffefaF5;box-shadow:0 18px 44px #0c2c4d12;backdrop-filter:blur(18px)}.quick-intro{display:flex;flex-direction:column;justify-content:center;padding:7px 13px}.quick-intro h2{margin:0 0 4px;font-size:23px;font-weight:700;letter-spacing:-.7px}.quick-intro p{margin:0;color:var(--muted);font-size:11px;line-height:1.5}.quick-card{display:flex;align-items:center;gap:12px;min-width:0;padding:12px;border:1px solid transparent;border-radius:15px;text-decoration:none;color:var(--navy);transition:transform .25s,border-color .25s,box-shadow .25s,background .25s}.quick-card:hover{transform:translateY(-4px);border-color:#e1e7e7;box-shadow:0 10px 22px #0c2c4d0c;color:var(--navy)}.quick-card.exam{background:linear-gradient(130deg,#edf5ff,#f8fbff)}.quick-card.results{background:linear-gradient(130deg,#eaf7f0,#f8fcf8)}.quick-card.fees{background:linear-gradient(130deg,#fff3e2,#fffbf5)}.quick-card.gallery{background:linear-gradient(130deg,#f8eefb,#fff9ff)}.quick-icon{display:grid;place-items:center;width:46px;height:46px;flex:0 0 46px;border-radius:13px;background:#d9eaff;color:#2468a0;transition:transform .25s}.results .quick-icon{background:#d4f1df;color:#16805c}.fees .quick-icon{background:#ffe6c5;color:#b66c12}.gallery .quick-icon{background:#f4dafa;color:#b13c91}.quick-card:hover .quick-icon{transform:rotate(-5deg) scale(1.06)}.quick-card strong{display:block;font-size:12px;font-weight:800}.quick-card small{display:block;margin-top:2px;color:#718092;font-size:10px}.quick-arrow{margin-left:auto;color:#8393a1;font-size:18px;transition:transform .2s}.quick-card:hover .quick-arrow{transform:translateX(3px)}
/* Highlights + announcements */
.below-hero{max-width:1580px;margin:28px auto 0;padding:0 clamp(18px,3.5vw,58px)}.highlights-row{display:grid;grid-template-columns:1.15fr .85fr;gap:18px;margin-bottom:24px}.stats-panel{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px;align-items:center;padding:18px;border:1px solid #e9e5dc;border-radius:19px;background:linear-gradient(110deg,#fffefa,#f8f7f0);box-shadow:0 8px 24px #0c2c4d07}.stat{display:flex;align-items:center;gap:9px;min-width:0}.stat-symbol{display:grid;place-items:center;width:36px;height:36px;flex:0 0 36px;border-radius:11px;background:#f5ead0;color:#a47b2e}.stat:nth-child(2) .stat-symbol{background:#e3eef7;color:#2a638d}.stat:nth-child(3) .stat-symbol{background:#e6f3ea;color:#347653}.stat:nth-child(4) .stat-symbol{background:#f3eafb;color:#8061a2}.stat-symbol svg{width:19px;height:19px;stroke:currentColor;fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}.stat strong{display:block;font-size:12px;line-height:1.3;color:var(--navy)}.stat small{display:block;color:#718092;font-size:9px;line-height:1.4}.student-feature{position:relative;min-height:90px;overflow:hidden;display:flex;align-items:center;justify-content:space-between;padding:16px 20px;border-radius:19px;background:linear-gradient(100deg,#dbeaf0,#edf5f2);border:1px solid #e4e9e4}.student-feature:after{content:'';position:absolute;right:-5px;bottom:-42px;width:56%;height:180%;background:url('uploads/WhatsApp Image 2025-07-08 at 11.34.47_5ca57a41.jpg') center 38%/cover no-repeat;mask-image:linear-gradient(90deg,transparent,#000 28%);opacity:.9}.student-feature p{position:relative;z-index:1;max-width:230px;margin:0;color:var(--navy);font-family:Georgia,serif;font-size:19px;font-style:italic;line-height:1.2}.student-feature p small{display:block;margin-bottom:5px;font-family:Inter,sans-serif;font-size:9px;font-style:normal;font-weight:800;letter-spacing:1.4px;text-transform:uppercase;color:#607e87}.announcements-section{padding:22px;border:1px solid #e8e9e3;border-radius:22px;background:#fffefa;box-shadow:0 12px 32px #0c2c4d08}.section-head{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:17px}.section-head h2{display:flex;align-items:center;gap:10px;margin:0;font-size:24px;letter-spacing:-.7px}.heading-icon{display:grid;place-items:center;width:36px;height:36px;border-radius:11px;background:#f8efd9;color:#98733a}.heading-icon svg{width:19px;height:19px;stroke:currentColor;fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}.view-all{display:inline-flex;align-items:center;gap:7px;padding:8px 13px;border-radius:999px;background:var(--navy);color:#fff;text-decoration:none;font-size:10px;font-weight:800;transition:transform .2s,background .2s}.view-all:hover{transform:translateY(-2px);background:#205985;color:#fff}.announcement-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}.announcement-card{display:flex;align-items:flex-start;gap:11px;min-width:0;min-height:88px;padding:14px;border:1px solid #e8eaf0;border-radius:14px;text-decoration:none;color:var(--navy);transition:transform .22s,box-shadow .22s,border-color .22s}.announcement-card:hover{transform:translateY(-3px);box-shadow:0 9px 22px #0c2c4d0c;color:var(--navy);border-color:#d6e1e8}.announcement-card:nth-child(4n+1){background:#fff1f3}.announcement-card:nth-child(4n+2){background:#eef6fd}.announcement-card:nth-child(4n+3){background:#fff6e8}.announcement-card:nth-child(4n+4){background:#f3effd}.mini-icon{display:grid;place-items:center;width:37px;height:37px;flex:0 0 37px;border-radius:11px;background:#ffdce5;color:#c33f69}.announcement-card:nth-child(4n+2) .mini-icon{background:#d8ecff;color:#2676b6}.announcement-card:nth-child(4n+3) .mini-icon{background:#ffe5bc;color:#a66a15}.announcement-card:nth-child(4n+4) .mini-icon{background:#e4dafa;color:#7655a7}.mini-icon svg{width:19px;height:19px}.announcement-card strong{display:block;margin:1px 0 2px;font-size:11px;font-weight:800;line-height:1.35}.announcement-card p{margin:0;color:#6f7e8c;font-size:10px;line-height:1.45}.announcement-card time{display:block;margin-top:5px;color:#8995a1;font-size:9px}
/* Retained school sections */
.container{max-width:1360px}.container.mt-5{margin-top:64px!important}.section-title{position:relative;margin:0 0 20px!important;text-align:left;font-size:clamp(1.5rem,2vw,2rem);font-weight:700;letter-spacing:-.6px}.section-title:after{content:'';display:block;width:48px;height:3px;margin-top:10px;border-radius:3px;background:linear-gradient(90deg,var(--navy),var(--gold))}.container>.text-center.fs-7,.container>.text-center.fs-6{color:var(--muted)}.info-box{position:relative;overflow:hidden;height:100%;padding:25px;background:#fff;border:1px solid var(--line);border-radius:20px;box-shadow:0 9px 26px #0c2c4d07;transition:transform .25s,box-shadow .25s,border-color .25s}.info-box:hover{transform:translateY(-5px);box-shadow:var(--shadow-hover);border-color:#d9e3e4}.mobile-box{min-height:88px;display:flex;align-items:center;justify-content:center;background:linear-gradient(145deg,#fff,#f6f8f8)}.mobile-box h6{font-size:13px;font-weight:800;color:var(--navy)!important}.info-box h4{font-size:18px;font-weight:700;margin-bottom:10px}.info-box p{margin:0;color:var(--muted);font-size:13px}.container .row.align-items-center.mb-5{padding:clamp(16px,2vw,28px);border:1px solid var(--line);border-radius:22px;background:#fffdf8b8;transition:box-shadow .3s,transform .3s}.container .row.align-items-center.mb-5:hover{box-shadow:var(--shadow);transform:translateY(-2px)}.container .row.align-items-center.mb-5 img{border-radius:16px!important;box-shadow:0 12px 28px #0c2c4d14!important;transition:transform .4s}.container .row.align-items-center.mb-5:hover img{transform:scale(1.012)}.container .card{overflow:hidden;border:1px solid #e7e8e2!important;border-radius:17px!important;background:#fff;box-shadow:0 8px 24px #0c2c4d09!important;transition:transform .25s,box-shadow .25s}.container .card:hover{transform:translateY(-4px);box-shadow:0 17px 34px #0c2c4d17!important}.container .card .btn{border-radius:9px;font-weight:700}.container .card-img-top{border-radius:13px!important}.gov,.card-title{font-weight:800;color:var(--navy)}.text-muted{color:#788797!important}.modal-content{border:1px solid #e8e6df;border-radius:22px;overflow:hidden;box-shadow:0 25px 80px #0c2c4d33}.modal-header{border-bottom:1px solid #ecebe5;background:#fffdf8}.modal-title{font-weight:800;color:var(--navy)}.modal-body img{border-radius:15px!important}.container .shadow.rounded.mx-auto{width:100%!important;max-width:100%;height:auto!important;overflow:hidden;border:5px solid white;border-radius:20px!important;box-shadow:0 16px 38px #0c2c4d13!important}.container iframe{display:block;width:100%!important;height:clamp(280px,35vw,450px)!important;padding:0!important;border:0;border-radius:15px}footer{margin-top:65px!important;padding:32px 16px!important;border-top:3px solid var(--gold);background:linear-gradient(110deg,#092744,#164c70)!important;color:#eaf1f5!important}footer a{color:#f1dba6!important}footer small{color:#c5d4df!important}
.ui-icon{display:inline-flex;align-items:center;justify-content:center;vertical-align:-.2em;margin-right:6px;color:#527b8b}.ui-icon svg{width:1.1em;height:1.1em;stroke:currentColor;fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}.reveal-ready{opacity:0;transform:translateY(14px);transition:opacity .65s ease,transform .65s cubic-bezier(.2,.75,.25,1)}.reveal-ready.revealed{opacity:1;transform:translateY(0)}@keyframes heroPhotoIn{from{transform:scale(1.035);filter:saturate(.8)}to{transform:scale(1);filter:saturate(1)}}
