/* ===== AJM immersive glass hero refinement ===== */
:root{--ajm-glass:rgba(255,253,248,.82);--ajm-glass-border:rgba(255,255,255,.78)}
body{background:linear-gradient(180deg,#f6f9fc 0%,#fffdf8 48%,#f5f8fb 100%)}
.navbar{background:rgba(255,253,248,.88)!important;backdrop-filter:blur(22px) saturate(145%)}
.ajm-hero{max-width:1700px;margin:22px auto 0;padding:0 clamp(14px,2.2vw,34px)}
.hero-panel{position:relative;isolation:isolate;display:block;min-height:clamp(470px,42vw,610px);overflow:hidden;border:1px solid rgba(255,255,255,.85);border-radius:clamp(20px,2.1vw,32px);background:#dcebf3;box-shadow:0 24px 70px rgba(12,44,77,.16)}
.hero-photo{position:absolute;inset:0;z-index:0;width:100%;height:100%;min-height:0;background:#dcebf3}
.hero-photo:before{content:"";position:absolute;z-index:2;inset:0;background:linear-gradient(90deg,rgba(255,253,248,.72) 0%,rgba(255,253,248,.42) 34%,rgba(255,253,248,.03) 72%),linear-gradient(0deg,rgba(6,31,55,.32) 0%,transparent 38%,rgba(6,31,55,.05) 100%);pointer-events:none}
.hero-photo #galleryCarousel,.hero-photo #galleryCarousel .carousel-inner,.hero-photo #galleryCarousel .carousel-item{height:100%;min-height:100%;}
.hero-photo #galleryCarousel .carousel-inner img{display:block;width:100%;height:100%!important;min-height:100%;max-height:none;object-fit:cover;object-position:center 48%;filter:saturate(1.04);transform:scale(1.01)}
.hero-photo #galleryCarousel .carousel-item.active img{animation:ajmHeroZoom 7s ease both}
@keyframes ajmHeroZoom{from{transform:scale(1.065)}to{transform:scale(1.01)}}
.hero-photo .carousel-control-prev,.hero-photo .carousel-control-next{z-index:4;width:7%;opacity:.9}
.hero-photo .carousel-control-prev-icon,.hero-photo .carousel-control-next-icon{width:42px;height:42px;background-color:rgba(8,43,76,.78);border:1px solid rgba(255,255,255,.55);backdrop-filter:blur(10px)}
.hero-copy{position:relative;z-index:3;display:flex;align-items:flex-start;justify-content:center;min-height:clamp(470px,42vw,610px);width:min(58%,760px);padding:clamp(28px,5vw,76px);background:linear-gradient(115deg,rgba(255,253,248,.91),rgba(255,253,248,.78) 72%,rgba(255,253,248,.16));border-right:1px solid rgba(255,255,255,.55);backdrop-filter:blur(16px) saturate(125%);-webkit-backdrop-filter:blur(16px) saturate(125%)}
.hero-copy:after{content:"";position:absolute;right:-1px;top:0;bottom:0;width:1px;background:linear-gradient(transparent,rgba(255,255,255,.9),transparent)}
.hero-copy .eyebrow{color:#536d81;line-height:1.6}
.hero-copy h1{max-width:620px;font-size:clamp(3rem,5.6vw,6rem);line-height:.98;letter-spacing:-.045em;margin-bottom:20px;text-wrap:balance}
.hero-copy h1 span{color:#245f88}
.hero-copy p{max-width:490px;color:#344f67;font-size:clamp(14px,1.12vw,17px);line-height:1.8}
.hero-actions{gap:12px;margin-top:28px}
.hero-link{min-height:48px;padding:13px 21px;font-size:12px}
.hero-note{right:clamp(16px,2.4vw,34px);bottom:clamp(16px,2.4vw,34px);padding:15px 19px;border:1px solid rgba(255,255,255,.82);background:rgba(255,253,248,.83);backdrop-filter:blur(18px);box-shadow:0 16px 40px rgba(7,34,58,.22)}
.quick-access{margin:-34px auto 0;padding:0 clamp(18px,4vw,64px)}
.quick-panel{grid-template-columns:190px repeat(4,minmax(0,1fr));gap:12px;padding:17px;border:1px solid rgba(255,255,255,.92);border-radius:25px;background:rgba(255,255,255,.84);box-shadow:0 22px 60px rgba(12,44,77,.14);backdrop-filter:blur(24px) saturate(145%);-webkit-backdrop-filter:blur(24px) saturate(145%)}
.quick-intro{padding:8px 15px}.quick-intro h2{font-size:clamp(21px,1.8vw,27px)}
.quick-card{padding:13px;border:1px solid rgba(255,255,255,.78);border-radius:17px}
.quick-card strong{font-size:13px}.quick-card small{font-size:11px}
.below-hero{margin-top:30px}
.stats-panel,.announcements-section,.container .row.align-items-center.mb-5,.info-box,.container .card{backdrop-filter:blur(12px)}
.section-head h2{font-size:clamp(20px,1.8vw,25px)}
.container{width:100%;max-width:1360px;padding-left:clamp(16px,2.4vw,32px);padding-right:clamp(16px,2.4vw,32px)}
.container iframe{width:100%!important}
