@media(max-width:390px){.hero-panel{min-height:590px}.hero-copy{padding:21px 17px}.hero-copy h1{font-size:2.45rem}.hero-actions{align-items:stretch}.hero-link{flex:1}.quick-access{padding:0 12px}.quick-panel{gap:5px;padding:9px}.quick-card{min-height:91px}.quick-card small{display:none}.quick-icon{width:35px;height:35px;flex-basis:35px}}
