/* ===== Single source of truth: responsive full-bleed hero ===== */
:root{--hero-radius:28px}
.ajm-hero{width:100%;max-width:1740px;margin:20px auto 0;padding:0 clamp(12px,2.5vw,40px)}
.hero-panel{display:block!important;position:relative!important;isolation:isolate;height:clamp(390px,31vw,490px)!important;min-height:390px!important;overflow:hidden;border:1px solid rgba(255,255,255,.82);border-radius:var(--hero-radius);background:#dbe8ed;box-shadow:0 22px 58px rgba(12,44,77,.14)}
.hero-photo{position:absolute!important;inset:0!important;z-index:0!important;width:100%!important;height:100%!important;min-height:0!important;overflow:hidden;background:#dbe8ed}
.hero-photo:before{content:"";position:absolute;z-index:2;inset:0;pointer-events:none;background:linear-gradient(90deg,rgba(9,39,68,.04),transparent 48%,rgba(9,39,68,.08)),linear-gradient(0deg,rgba(8,35,61,.22),transparent 32%)}
.hero-photo #galleryCarousel{position:absolute;inset:0;height:100%!important;min-height:0!important;margin:0!important;border:0!important;border-radius:0!important;box-shadow:none!important;background:#dbe8ed}
.hero-photo #galleryCarousel .carousel-inner,.hero-photo #galleryCarousel .carousel-item{height:100%!important;min-height:0!important}
.hero-photo #galleryCarousel .carousel-inner img{display:block;width:100%;height:100%!important;min-height:0!important;max-height:none!important;object-fit:cover;object-position:center 46%;filter:saturate(1.02) contrast(1.01)}
.hero-photo #galleryCarousel .carousel-item.active img{animation:heroPhotoIn 7s ease both}
/* The copy container is transparent. Only its pseudo-element supplies the glass surface. */
.hero-copy{position:absolute!important;inset:0!important;z-index:4!important;display:flex;flex-direction:column;align-items:flex-start;justify-content:center;width:100%!important;height:100%!important;min-height:0!important;padding:clamp(28px,4.2vw,66px) clamp(28px,4.8vw,78px)!important;overflow:hidden;background:transparent!important;border:0!important;backdrop-filter:none!important;-webkit-backdrop-filter:none!important;pointer-events:none}
.hero-copy:before{content:"";position:absolute;z-index:0;inset:0 auto 0 0;width:min(79%,1120px);height:100%;pointer-events:none;background:linear-gradient(90deg,rgba(255,253,248,.97) 0%,rgba(255,253,248,.94) 53%,rgba(255,253,248,.81) 72%,rgba(255,253,248,.53) 86%,rgba(255,253,248,0) 100%);backdrop-filter:blur(11px);-webkit-backdrop-filter:blur(11px);mask-image:linear-gradient(90deg,#000 0%,#000 57%,rgba(0,0,0,.78) 76%,transparent 100%);-webkit-mask-image:linear-gradient(90deg,#000 0%,#000 57%,rgba(0,0,0,.78) 76%,transparent 100%)}
.hero-copy:after{display:none!important}
.hero-copy>*{position:relative;z-index:1;pointer-events:auto}
.hero-copy .eyebrow{margin:0 0 16px;font-size:10px;letter-spacing:1.65px;color:#526d82;line-height:1.5}
.hero-copy h1{max-width:720px;margin:0 0 16px;font-size:clamp(3rem,5.15vw,5rem)!important;font-weight:700;line-height:.94;letter-spacing:-.055em;text-wrap:balance}
.hero-copy h1 span{display:block;color:#2c668b}
.hero-copy p{max-width:520px;margin:0;color:#334f68;font-size:clamp(14px,1.1vw,17px);line-height:1.72}
.hero-actions{display:flex;flex-wrap:wrap;align-items:center;gap:10px;margin:22px 0 0}
.hero-link{min-height:46px;padding:12px 19px;font-size:12px;gap:9px}
.hero-link-primary{background:linear-gradient(110deg,#0b2c4c,#1e608d)}
