.hero-note{z-index:6;right:clamp(14px,2vw,28px);bottom:clamp(14px,2vw,28px);max-width:min(330px,32%);padding:11px 14px;background:rgba(255,253,248,.91);border:1px solid rgba(255,255,255,.88);backdrop-filter:blur(16px);-webkit-backdrop-filter:blur(16px);box-shadow:0 12px 30px rgba(8,35,61,.18)}
