  <script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/js/bootstrap.bundle.min.js"></script>
  <script>
  (()=>{
    const track=document.getElementById('ajmTickerTrack');
    const toggle=document.getElementById('ajmTickerToggle');
    if(track&&!track.dataset.loopReady){
      const originalItems=Array.from(track.children);
      originalItems.forEach(item=>{
        const clone=item.cloneNode(true);
        clone.setAttribute('aria-hidden','true');
        clone.querySelectorAll('svg').forEach(icon=>icon.setAttribute('aria-hidden','true'));
        track.appendChild(clone);
      });
      track.dataset.loopReady='true';
    }
    if(track&&toggle){toggle.addEventListener('click',()=>{const paused=track.classList.toggle('is-paused');toggle.textContent=paused?'▶':'Ⅱ';toggle.setAttribute('aria-pressed',String(paused));toggle.setAttribute('aria-label',paused?'Resume announcement ticker':'Pause announcement ticker');});}
    const items=document.querySelectorAll('.container.mt-5, .announcements-section, .stats-panel');
    items.forEach(el=>el.classList.add('reveal-ready'));
    if('IntersectionObserver' in window){const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('revealed');observer.unobserve(entry.target);}}),{threshold:.08});items.forEach(el=>observer.observe(el));}else{items.forEach(el=>el.classList.add('revealed'));}
    const carousel=document.getElementById('galleryCarousel');if(carousel&&window.matchMedia('(prefers-reduced-motion: reduce)').matches){bootstrap.Carousel.getOrCreateInstance(carousel,{interval:false});}
  })();
  </script>
